PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;
PRAGMA cache_size = -16384;
PRAGMA foreign_keys = ON;
PRAGMA temp_store = MEMORY;

CREATE TABLE IF NOT EXISTS company (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  companyNameCN TEXT,
  companyNameEN TEXT,
  companyAddressCN TEXT,
  companyAddressEN TEXT,
  companyTel TEXT,
  companyFax TEXT,
  signAt TEXT,
  logoUrl TEXT,
  themeColor TEXT,
  fontSize INTEGER,
  headerProduction TEXT,
  headerInvoice TEXT,
  headerPacking TEXT,
  headerSales TEXT
);

CREATE TABLE IF NOT EXISTS customers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL UNIQUE,
  address TEXT,
  tel TEXT,
  fax TEXT,
  contact TEXT
);

CREATE TABLE IF NOT EXISTS orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  contractNo TEXT,
  invoiceNo TEXT,
  blNo TEXT,
  invoiceDate TEXT,
  shipmentDate TEXT,
  shipFrom TEXT,
  shipTo TEXT,
  shippedPerSs TEXT,
  forwarder TEXT,
  customerId INTEGER,
  customerName TEXT,
  totalUSD REAL,
  createdAt TEXT,
  updatedAt TEXT,
  productType INTEGER DEFAULT 1,
  extras TEXT,
  status TEXT DEFAULT '已创建',
  template TEXT,
  deletedAt TEXT,
  paymentDate TEXT,
  FOREIGN KEY(customerId) REFERENCES customers(id)
);

CREATE TABLE IF NOT EXISTS order_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  orderId INTEGER NOT NULL,
  sortIndex INTEGER,
  model TEXT,
  quantity REAL,
  packages REAL,
  weight REAL,
  actualWeight REAL,
  packing TEXT,
  labelWeight REAL,
  safetyFactor TEXT,
  cleanliness TEXT,
  unit TEXT,
  unitPrice REAL,
  amount REAL,
  labelBatchNo TEXT,
  label TEXT,
  extras TEXT,
  FOREIGN KEY(orderId) REFERENCES orders(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  model TEXT NOT NULL,
  description TEXT,
  estimatedWeight REAL,
  labelWeight REAL,
  safetyFactor TEXT,
  cleanliness TEXT,
  unit TEXT,
  createdAt TEXT,
  updatedAt TEXT,
  source TEXT DEFAULT 'manual',
  actualWeight REAL,
  labelBatchNo TEXT,
  label TEXT,
  marks TEXT,
  template TEXT,
  productType INTEGER DEFAULT 1,
  UNIQUE(model, productType)
);

CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT NOT NULL UNIQUE,
  password TEXT NOT NULL,
  displayName TEXT,
  avatar TEXT,
  role TEXT DEFAULT 'user',
  status TEXT DEFAULT 'active',
  lastLoginAt TEXT,
  createdAt TEXT NOT NULL,
  updatedAt TEXT NOT NULL,
  createdBy INTEGER,
  FOREIGN KEY(createdBy) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS operation_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  userId INTEGER,
  username TEXT,
  operation TEXT NOT NULL,
  module TEXT NOT NULL,
  target TEXT,
  details TEXT,
  ipAddress TEXT,
  userAgent TEXT,
  status TEXT DEFAULT 'success',
  errorMessage TEXT,
  createdAt TEXT NOT NULL,
  FOREIGN KEY(userId) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  userId INTEGER NOT NULL,
  token TEXT NOT NULL UNIQUE,
  expiresAt TEXT NOT NULL,
  ipAddress TEXT,
  userAgent TEXT,
  createdAt TEXT NOT NULL,
  FOREIGN KEY(userId) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS document_templates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  type TEXT NOT NULL,
  version TEXT DEFAULT '1.0',
  config TEXT NOT NULL,
  isDefault INTEGER DEFAULT 0,
  createdBy INTEGER,
  createdAt TEXT NOT NULL,
  updatedAt TEXT NOT NULL,
  FOREIGN KEY(createdBy) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS order_configs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  category TEXT NOT NULL,
  value TEXT NOT NULL,
  sortIndex INTEGER DEFAULT 0,
  createdAt TEXT NOT NULL,
  updatedAt TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_customers_name ON customers(name);
CREATE INDEX IF NOT EXISTS idx_products_model ON products(model);
CREATE INDEX IF NOT EXISTS idx_products_description ON products(description);
CREATE INDEX IF NOT EXISTS idx_products_model_type ON products(model, productType);
CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customerId);
CREATE INDEX IF NOT EXISTS idx_orders_created ON orders(createdAt);
CREATE INDEX IF NOT EXISTS idx_orders_contract ON orders(contractNo);
CREATE INDEX IF NOT EXISTS idx_orders_invoice ON orders(invoiceNo);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(orderId);
CREATE INDEX IF NOT EXISTS idx_order_items_model ON order_items(model);
CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);
CREATE INDEX IF NOT EXISTS idx_sessions_token ON sessions(token);
CREATE INDEX IF NOT EXISTS idx_operation_logs_created ON operation_logs(createdAt);
CREATE INDEX IF NOT EXISTS idx_document_templates_type ON document_templates(type);
CREATE INDEX IF NOT EXISTS idx_document_templates_default ON document_templates(type, isDefault);
CREATE INDEX IF NOT EXISTS idx_order_configs_category ON order_configs(category);

